737: export function openPikachuInteraction() {
738:   const opp = { UP: "DOWN", DOWN: "UP", LEFT: "RIGHT", RIGHT: "LEFT" };
739:   state.pikachu.dir = opp[state.player.dir] || "DOWN";
740:   const mood = PIKACHU_MOODS[state.pikachu.moodIndex % PIKACHU_MOODS.length];
741:   state.pikachu.moodIndex++;
742:   triggerEmote(mood.emote, 2400);
743:   audio.playSfx("pika");
744:   openDialogue(mood.title, mood.text, { pikachuMood: mood });
745: }
746: 
747: function openElevatorMenu(elevatorConst) {
748:   audio.playSfx("blip");
749:   const floors = ELEVATOR_FLOORS[elevatorConst];
750:   state.dialogue = {
751:     title: `${state.currentZone.displayName} — Select Floor`,
752:     pages: ["Which floor would you like to go to?"],
753:     pageIndex: 0,
754:     elevatorConst,
755:     elevatorOptions: floors,
756:   };
757:   renderDialogueModal();
758: }
759: 
760: export function openDialogue(title, rawText, extra = {}) {
761:   const pages = String(rawText || "")
762:     .split(/\n\n+/)
763:     .map((p) => p.trim())
764:     .filter(Boolean);
765:   if (pages.length === 0) pages.push("...");
766:   state.dialogue = {
767:     title,
768:     pages,
769:     pageIndex: 0,
770:     ...extra,
771:   };
772:   renderDialogueModal();
773: }
774: 
775: function advanceDialogue() {
776:   if (!state.dialogue) return;
777:   if (state.dialogue.pageIndex + 1 < state.dialogue.pages.length) {
778:     state.dialogue.pageIndex++;
779:     audio.playSfx("blip");
780:     renderDialogueModal();
781:   } else {
782:     state.dialogue = null;
783:     renderDialogueModal();
784:   }
785: }
