      };
    }"""], check=True)
    time.sleep(0.3)
    subprocess.run(["playwright-cli", "screenshot", "--filename=/tmp/opencode/battle-menu-check.jpg"], check=True)
    subprocess.run(["playwright-cli", "close"], check=True)
finally:
    srv.terminate()
    srv.wait()
'

