    `${b.isTrainer ? "Enemy " : "Wild "}${foe.nickname}\nfainted!`,
    `${pMon.nickname} gained\n${expGain} EXP. Points!`
  );
  awardExpAndCheckLevelUp(pMon, expGain, msgs);

