in_moves = False
for line in em_txt.splitlines():
    s = line.strip()
    m_lbl = re.match(r"^([A-Za-z0-9_]+)EvosMoves:", s)
    if m_lbl:
        raw_m = m_lbl.group(1)
        # Convert CamelCase to UPPER_SNAKE
        up = re.sub(r"([a-z])([A-Z])", r"\1_\2", raw_m).upper()
        if up == "NIDORAN_F":
            cur_mon = "NIDORAN_F"
        elif up == "NIDORAN_M":
            cur_mon = "NIDORAN_M"
        elif up == "MR_MIME":
            cur_mon = "MR_MIME"
        else:
            cur_mon = up.replace("_", "") if up not in ("FARFETCH_D",) else "FARFETCHD"
        learnsets[cur_mon] = []
        in_moves = False
    elif cur_mon:
