    subprocess.run(["playwright-cli", "open", "http://127.0.0.1:8765/index.html"], check=True)
    subprocess.run(["playwright-cli", "resize", "1280", "720"], check=True)
    subprocess.run(["playwright-cli", "eval", """() => {
      // 1. Check initial Pikachu friendship == 0
      const initialFriendship = window.POKEYELLOW.state.pikachu.friendship;

      // 2. Test Daisy in BLUES_HOUSE (scripts/BluesHouse.asm & scripts/PalletTown.asm)
      window.POKEYELLOW.loadZone("BLUES_HOUSE");
      const daisy1 = window.POKEYELLOW.state.npcs.find(n => n.name === "BLUESHOUSE_DAISY1");
      const townMapObj = window.POKEYELLOW.state.npcs.find(n => n.name === "BLUESHOUSE_TOWN_MAP");
      window.POKEYELLOW.triggerNpcDialogue(daisy1);
      const firstDaisyText = window.POKEYELLOW.state.dialogue.pages.join(" | ");
      const afterFirstTalk = {
        daisyStillVisible: !daisy1.collected && daisy1.defaultVisible,
        mapHidden: townMapObj.collected,
        gotTownMap: window.POKEYELLOW.state.events.gotTownMap
      };
      // Talk to Daisy again in Blues House
      window.POKEYELLOW.triggerNpcDialogue(daisy1);
      const secondDaisyText = window.POKEYELLOW.state.dialogue.pages.join(" | ");

      // Exit to PALLET_TOWN -> triggers PalletTownDaisyScript -> re-enter BLUES_HOUSE
      window.POKEYELLOW.loadZone("PALLET_TOWN");
      window.POKEYELLOW.loadZone("BLUES_HOUSE");
      const daisy2 = window.POKEYELLOW.state.npcs.find(n => n.name === "BLUESHOUSE_DAISY2");
      window.POKEYELLOW.triggerNpcDialogue(daisy2);
      const walkingDaisyCheck = {
        daisyWalkingEvent: window.POKEYELLOW.state.events.daisyWalking,
        daisy2Visible: daisy2.defaultVisible && !daisy2.collected,
        daisy2Text: window.POKEYELLOW.state.dialogue.pages[0]
      };
      window.POKEYELLOW.state.dialogue = null;

      // 3. Test Evolution Cancellation by pressing B during EvolveMon animation
      const charMon = window.POKEYELLOW.state.party.find(m => m.species === "CHARMANDER");
      charMon.level = 15;
      window.POKEYELLOW.triggerWildEncounter([3, "PIDGEY"]);
      window.POKEYELLOW.state.battle.activePlayerIdx = 2; // CHARMANDER
      // Use RARE CANDY (index 7 in bag)
      window.POKEYELLOW.state.battle.menuState = "BAG_MENU";
      window.POKEYELLOW.state.battle.bagCursor = 7;
      window.POKEYELLOW.handleBattleInput("A"); // RED used RARE CANDY!
      window.POKEYELLOW.handleBattleInput("A"); // CHARMANDER grew to level 16!
      window.POKEYELLOW.handleBattleInput("A"); // Enters EVOLVING state!
      const evolvingState = window.POKEYELLOW.state.battle.menuState;
      // Press B to cancel evolution!
      window.POKEYELLOW.handleBattleInput("B");
      const afterCancel = {
        menuState: window.POKEYELLOW.state.battle.menuState,
        log: window.POKEYELLOW.state.battle.log,
        speciesAfterCancel: charMon.species,
        levelAfterCancel: charMon.level
      };

      // Now trigger evolution again so screenshot shows the interactive EvolveMon stage with STOP EVOLUTION (B)!
      window.POKEYELLOW.handleBattleInput("A"); // back to MAIN_MENU
      window.POKEYELLOW.state.battle.menuState = "BAG_MENU";
      window.POKEYELLOW.state.battle.bagCursor = 7;
      window.POKEYELLOW.handleBattleInput("A"); // RED used RARE CANDY!
      window.POKEYELLOW.handleBattleInput("A"); // CHARMANDER grew to level 17!
      window.POKEYELLOW.handleBattleInput("A"); // Enters EVOLVING state!

      return {
        initialFriendship,
        firstDaisyText,
        afterFirstTalk,
        secondDaisyText,
        walkingDaisyCheck,
        evolvingState,
        afterCancel
      };
    }"""], check=True)
    time.sleep(0.25)
    subprocess.run(["playwright-cli", "screenshot", "--filename=/tmp/opencode/final-verify.jpg"], check=True)
    subprocess.run(["playwright-cli", "close"], check=True)
finally:
    srv.terminate()
    srv.wait()
'

