        startMenuOpen: window.POKEYELLOW.state.startMenu.open,
        wrappedToBottom,
        wrappedToTop,
        subViewOpened,
        returnedToTopLevel,
        rememberedCursor: window.POKEYELLOW.state.startMenu.cursor
      };
